scwin.vScrenID = 'ULDSTF51000.xml';
scwin.gLdMktTp = js_market; // 세션의 시장구분
scwin.gType = "";
scwin.rtn = "";
scwin.gMsg = "";
scwin.gMsgCnt = 0;
scwin.gUsrId = js_id;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setHeader = function() {
    //dts_DisclsForm.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=FORM_LIST_INOUT";
    //dts_DisclsForm.reset();

    dts_newFormNm.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NEW_MYFORM_NM_INOUT";
    dts_newFormNm.Reset();
    dts_newFormNm.insertRow();
};
scwin.fn_SetCode = function() {
    if (scwin.gLdMktTp == "9") {
        $c.stf.setObjectValue(rdo_MktTpCd, 'A');
    } else {
        $c.stf.setObjectValue(rdo_MktTpCd, scwin.gLdMktTp);
    }

    // 대분류 셋팅
    dts_FormUpclss.DataID = "/CodeAction.do?method=listFormUpclss&For=R";
    dts_FormUpclss.Reset();
};


//사용자서식 리스트
scwin.fn_myFormList = function() {
    var url = "/MyFormPage.do?method=listMyForm&inputMessageId=MYFORM_LIST_INOUT&outputMessageId=MYFORM_LIST_INOUT" + "&USR_ID=" + scwin.gUsrId + "&MYFORM_NM_SEQ=" + $c.stf.getObjectValue(cmb_myFormNmList) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_myFormList.DataID = encodeURI(url);
    dts_myFormList.Reset();
    $c.cm.ShowWin(grd_myFormList);
};
scwin.fn_myFormNmList = function() {
    // 사용자서식 명칭 리스트
    var url = "/MyFormPage.do?method=listMyFormNm&For=C" + "&USR_ID=" + scwin.gUsrId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_myFormNmList.DataID = encodeURI(url);
    dts_myFormNmList.Reset();
};



//서식목록 가져오기
scwin.fn_Search = function() {
    var url = "/MyFormPage.do?method=listFormInfo&inputMessageId=FORM_LIST_INOUT&outputMessageId=FORM_LIST_INOUT" + "&FORM_KOR_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MktTpCd) + "&FORM_UPCLSS_CD=" + $c.stf.getObjectValue(cmb_FormUpclssCd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DisclsForm.DataID = encodeURI(url);
    dts_DisclsForm.reset();
    $c.cm.ShowWin(grd_DisclsForm);
};
scwin.fn_newSave = function() {
    if ($c.stf.getObjectValue(txb_myFormNm) == '') {
        $c.win.alert("사용자 서식 그룹 명칭을 입력하여 주십시요.");
        txb_myFormNm.focus();
        return;
    }
    if (!scwin.checkMaxLength1(txb_myFormNm, 20, "사용자 서식 그룹 명칭")) {
        txb_myFormNm.focus();
        return;
    }
    scwin.rtn = confirm('사용자 서식 명칭을 신규추가 하시겠습니까?');
    if (scwin.rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_newFormNm.setCellData(1, "USR_ID", scwin.gUsrId);
        trs_Save.Action = "/MyFormPage.do?method=saveMyFormGrpNm&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_newFormNm)";
        trs_Save.Post();
    }
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};


//체크 초기화
scwin.fn_reSetCheck = function(sval) {
    //데이터셋 체크박스 초기화
    for (var i = 1; i <= sval.getTotalRow(); i++) {
        sval.setCellData(i, "CHK_FLAG", 0);
    }
};



/*----------------------------------------------------------------------------
	** 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다. 
-------------------------------------------------------------------------------*/
scwin.fn_cntDatasetRowCheck = function(sval) {
    var cCnt = 0;
    for (i = 1; i <= sval.getTotalRow(); i++) {
        if (sval.getCellData(i, "CHK_FLAG") == 1) {
            cCnt++;
        }
    }
    if (cCnt == 0) {
        return false;
    } else {
        return true;
    }
};




