scwin.fn_SelectTakeOver = async function() {
    var checkTcnt = 0;
    var checkFlag = "";
    var tmpInt = 1;
    scwin.gMsgCnt = 0;
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
    if (!scwin.fn_cntDatasetRowCheck(dts_DisclsForm)) {
        $c.win.alert("추가 할 서식을 선택하여 주십시요");
    } else {
        for (var i = 1; i <= dts_DisclsForm.getTotalRow(); i++) {
            if (dts_DisclsForm.getCellData(i, "CHK_FLAG") == 1) {
                checkFlag = "T";
                if (dts_myFormList.getTotalRow() == 0) {
                    checkTcnt++;
                    dts_myFormList.insertRow();
                    dts_myFormList.setCellData(tmpInt, "LD_MKT_TP_NM", dts_DisclsForm.getCellData(i, "LD_MKT_TP_NM"));
                    dts_myFormList.setCellData(tmpInt, "FORM_CD", dts_DisclsForm.getCellData(i, "FORM_CD"));
                    dts_myFormList.setCellData(tmpInt, "FORM_KOR_NM", dts_DisclsForm.getCellData(i, "FORM_KOR_NM"));
                    dts_myFormList.setCellData(tmpInt, "FORM_UPCLSS_NM", dts_DisclsForm.getCellData(i, "FORM_UPCLSS_NM"));
                    dts_myFormList.setCellData(tmpInt, "FORM_ADM_INST_TP_NM", dts_DisclsForm.getCellData(i, "FORM_ADM_INST_TP_NM"));
                    dts_myFormList.setCellData(tmpInt, "USE_NM", dts_DisclsForm.getCellData(i, "USE_NM"));
                    dts_myFormList.setCellData(tmpInt, "MYFORM_NM_SEQ", $c.stf.getObjectValue(cmb_myFormNmList));
                    dts_myFormList.setCellData(tmpInt, "USR_ID", scwin.gUsrId);
                } else {
                    for (var j = 1; j <= dts_myFormList.getTotalRow(); j++) {
                        if (dts_DisclsForm.getCellData(i, "FORM_CD") == dts_myFormList.getCellData(j, "FORM_CD")) {
                            checkFlag = "F";
                            scwin.gMsgCnt++;
                            break;
                        }
                    }
                    if (checkFlag == 'T') {
                        checkTcnt++;
                        dts_myFormList.insertRow(dts_myFormList.getRowPosition() - 1);
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "LD_MKT_TP_NM", dts_DisclsForm.getCellData(i, "LD_MKT_TP_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "FORM_CD", dts_DisclsForm.getCellData(i, "FORM_CD"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "FORM_KOR_NM", dts_DisclsForm.getCellData(i, "FORM_KOR_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "FORM_UPCLSS_NM", dts_DisclsForm.getCellData(i, "FORM_UPCLSS_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "FORM_ADM_INST_TP_NM", dts_DisclsForm.getCellData(i, "FORM_ADM_INST_TP_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "USE_NM", dts_DisclsForm.getCellData(i, "USE_NM"));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "MYFORM_NM_SEQ", $c.stf.getObjectValue(cmb_myFormNmList));
                        dts_myFormList.setCellData(dts_myFormList.getRowPosition(), "USR_ID", scwin.gUsrId);
                    }
                }
            }
        }
        if (checkTcnt == 0) {
            $c.win.alert("선택한 서식 모두 이미 추가되어 있습니다.");
        }
    }
};
scwin.fn_delete = function() {
    if (!scwin.fn_cntDatasetRowCheck(dts_myFormList)) {
        $c.win.alert("삭제할 서식을 선택하여 주십시요");
    } else {
        for (i = dts_myFormList.getTotalRow(); i > 0; i--) {
            if (dts_myFormList.getCellData(i, "CHK_FLAG") == 1) {
                //alert("i ===== " + i);
                $c.cp.removeRow(dts_myFormList, i);
            }
        }
    }
};
scwin.fn_Save = function() {
    if ($c.stf.getObjectValue(cmb_myFormNmList) == '') {
        $c.win.alert("사용자 서식 그룹을 선택하여 주십시요");
        return;
    }
    var rtn = confirm('서식목록을 저장 하시겠습니까?');
    if (scwin.rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_FormList.Action = "/MyFormPage.do?method=saveMyFormList&inputMessageId=MYFORM_LIST_INOUT" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_FormList.KeyName = "toinb_dataid4";
        trs_FormList.KeyValue = "JSP(I:pInput=dts_myFormList)";
        trs_FormList.Post();
    }
};
scwin.grd_DisclsForm_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_newSave_onclick = function() {
    scwin.fn_newSave();
};
scwin.btn_Select_HandOver_onclick = function() {
    if (cmb_myFormNmList.getSelectedIndex() != -1) {
        scwin.fn_SelectTakeOver();
    }
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_myFormMgt_onclick = async function() {
    var url = "/indinfo/ULDSTF51010.gfm";
    var winTitle = "사용자서식 그룹관리";
    await $c.frame.CreateDialogFrame("MYFORMGRP", url, winTitle, 100, 10, 600, 400, "window");
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert('사용자서식 명칭이 저장되었습니다.');
    //사용자 서식 목록 을  다시 불러옴
    txb_myFormNm.setValue("");
    scwin.fn_myFormNmList();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert('사용자서식 명칭이 저장에 실패했습니다.');
};
scwin.dts_DisclsForm_OnLoadError = function() {
    $c.stf.alert_error("OnLoadError => " + dts_DisclsForm);
    $c.cm.CloseWin('', grd_DisclsForm);
};
scwin.dts_DisclsForm_OnLoadCompleted = function(rowcount) {
    if (dts_DisclsForm.errorMsg) {
        $c.win.alert("OnLoadCompleted => " + dts_DisclsForm.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_DisclsForm);
};
scwin.dts_myFormList_OnLoadError = function() {
    $c.stf.alert_error("OnLoadError => " + dts_myFormList);
    $c.cm.CloseWin('', grd_myFormList);
};
scwin.dts_myFormList_OnLoadCompleted = function(rowcount) {
    if (dts_myFormList.errorMsg) {
        $c.win.alert("OnLoadCompleted => " + dts_myFormList.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page2);
    }
    $c.cm.CloseWin(rowcount, grd_myFormList);
};
scwin.grd_DisclsForm_OnHeadCheckClick = function(col, colid, bCheck) {
    var gcnt = dts_DisclsForm.getTotalRow();
    if (gcnt > 0) {
        grd_DisclsForm.Redraw = false;
        for (var i = 1; i <= gcnt; i++) {
            dts_DisclsForm.setCellData(i, "CHK_FLAG", bCheck);
        }
        grd_DisclsForm.Redraw = true;
    }
};
scwin.grd_myFormList_OnHeadCheckClick = function(col, colid, bCheck) {
    var gcnt = dts_myFormList.getTotalRow();
    if (gcnt > 0) {
        grd_myFormList.Redraw = false;
        for (var i = 1; i <= gcnt; i++) {
            dts_myFormList.setCellData(i, "CHK_FLAG", bCheck);
        }
        grd_myFormList.Redraw = true;
    }
};
scwin.dts_myFormNmList_OnLoadCompleted = function(rowcount) {
    dts_myFormList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MYFORM_LIST_INOUT";
    dts_myFormList.reset();
};
scwin.dts_myFormNmList_OnLoadError = function() {
    $c.stf.alert_error("OnLoadError => " + dts_myFormNmList);
};
scwin.cmb_myFormNmList_OnSelChange2 = function() {
    scwin.fn_myFormList();
};
scwin.cmb_myFormNmList_OnSelected = function() {

};
scwin.trs_FormList_OnSuccess = function() {
    $c.win.alert("서식저장에 성공하였습니다.");
    scwin.fn_myFormList();
    scwin.fn_reSetCheck(dts_DisclsForm);
};
scwin.trs_FormList_OnFail = function() {
    $c.win.alert("서식 저장에 실패했습니다.");
};
scwin.gform_onload = function() {
    scwin.fn_setHeader();

    // 대분류 콤보에 값 셋팅
    scwin.fn_SetCode();

    //사용자 서식 명칭 리스트 
    scwin.fn_myFormNmList();
};
